-- Prototype plants / types from 0002 — only these, and only while nothing (e.g. budget
-- rows) still points at them. Real types with no machine yet stay for later imports.
do $$
declare r record;
begin
  for r in select s.code from public.sites s
           where code in ('UT', 'PCD', 'SA', 'NY1')
             and not exists (select 1 from public.assets a where a.site = s.code) loop
    begin delete from public.sites where code = r.code;
    exception when foreign_key_violation then null; end;
  end loop;
  delete from public.asset_types t
    where t.name not in ('Axial Blower', 'Axial Split Pump', 'Bag Strainer', 'Belt Conveyor', 'Blower/Fan', 'Buffer Fluid Unit', 'Centrifugal Pump', 'Centrifugal Separator', 'Compressor', 'Cooling Tower', 'Decanter Separator', 'Feeder', 'Filter', 'Furnace', 'Gear Pump', 'Gearbox', 'Hydraulic Unit', 'Integr. Gear Compressor', 'Lobe Blower', 'M/C', 'Magnetic Pump', 'Mechanical Agitator', 'Metering Pump', 'Mixer/Blender', 'Motor', 'Motor Gearbox', 'Oil Unit', 'Other', 'Pelletizer', 'Pump', 'Radial Split Pump', 'Reciprocating Compressor', 'Reciprocating Pump', 'Roller Conveyor', 'Rotary Dryer', 'Scrapper Agitator', 'Screw Blower', 'Screw Compressor', 'Self-Cleaning Strainer', 'Single Screw Extruder', 'Steam Turbine', 'Tumbler Mixer', 'Twin Screw Extruder', 'Vane Pump', 'Vibrating Conveyor')
      and not exists (select 1 from public.assets a where a.type = t.name);
end $$;

select public.recompute_all_health();
